INSERT INTO brands (id,name,description) VALUES ('daily-naturals','Daily Naturals','Австралійський професійний бренд Clean Beauty із веганськими формулами салонної якості. Засоби орієнтовані на результативний догляд, турботу про здоров’я волосся та відповідальніший вплив на довкілля.'),('esla','ESLA Italy','Італійський професійний бренд догляду за волоссям, що поєднує сучасні дослідження, високоефективні веганські формули та відповідальний підхід до виробництва. Продукти розроблено й виготовлено в Італії.') ON CONFLICT(id) DO UPDATE SET name=excluded.name,description=excluded.description;
INSERT INTO product_lines (id,brand_id,name,short_description,description,hair_types,purposes,benefits,keywords,image) VALUES ('daily-naturals-everyday-balancing','daily-naturals','Everyday Balancing','Щоденне очищення, зволоження та свіжість','Лінійка Daily Naturals для потреби «щоденний збалансований догляд». Професійні формули Clean Beauty підтримують здоровий вигляд волосся та поєднують ефективність із комфортним щоденним доглядом.','["Усі типи волосся"]','["Щоденний збалансований догляд","Зволоження"]','["М’яко очищає","Підтримує життєву силу","Надає свіжості"]','["баланс","щодня","свіжість"]','/images/daily-naturals/daily-naturals-everyday-balancing.webp'),('daily-naturals-intense-hydrating','daily-naturals','Intense Hydrating','Інтенсивне зволоження сухого та пошкодженого волосся','Лінійка Daily Naturals для потреби «глибоке зволоження». Професійні формули Clean Beauty підтримують здоровий вигляд волосся та поєднують ефективність із комфортним щоденним доглядом.','["Сухе","Пошкоджене","Ламке"]','["Глибоке зволоження","Відновлення м’якості"]','["Насичує вологою","Робить волосся гладеньким","Повертає доглянутий вигляд"]','["волога","м’якість","відновлення"]','/images/daily-naturals/daily-naturals-intense-hydrating.webp'),('daily-naturals-full-bodied-volumising','daily-naturals','Full-Bodied Volumising','Об’єм і пружність для тонкого волосся','Лінійка Daily Naturals для потреби «надання об’єму». Професійні формули Clean Beauty підтримують здоровий вигляд волосся та поєднують ефективність із комфортним щоденним доглядом.','["Тонке","Позбавлене об’єму"]','["Надання об’єму","Візуальна густота"]','["Додає пишності","Підтримує пружність","Не обтяжує"]','["об’єм","густота","пружність"]','/images/daily-naturals/daily-naturals-full-bodied-volumising.webp'),('daily-naturals-anti-frizz-smoothing','daily-naturals','Anti-Frizz Smoothing','Розгладження та контроль пухнастого волосся','Лінійка Daily Naturals для потреби «контроль пухнастості». Професійні формули Clean Beauty підтримують здоровий вигляд волосся та поєднують ефективність із комфортним щоденним доглядом.','["Пухнасте","Неслухняне","Сухе"]','["Контроль пухнастості","Розгладження"]','["Пом’якшує","Надає блиску","Робить волосся слухнянішим"]','["гладкість","контроль","блиск"]','/images/daily-naturals/daily-naturals-anti-frizz-smoothing.webp'),('daily-naturals-blonde-toning','daily-naturals','Blonde Toning','Нейтралізація жовтих відтінків світлого волосся','Лінійка Daily Naturals для потреби «нейтралізація жовтизни». Професійні формули Clean Beauty підтримують здоровий вигляд волосся та поєднують ефективність із комфортним щоденним доглядом.','["Блонд","Освітлене","Сиве"]','["Нейтралізація жовтизни","Підтримка холодного відтінку"]','["Освіжає блонд","Зволожує","Надає сяйва"]','["блонд","фіолетовий пігмент","холодний відтінок"]','/images/daily-naturals/daily-naturals-blonde-toning.webp'),('daily-naturals-scalp-clearing','daily-naturals','Scalp Clearing','Заспокоєння сухої та схильної до лущення шкіри голови','Лінійка Daily Naturals для потреби «зменшення дискомфорту шкіри голови». Професійні формули Clean Beauty підтримують здоровий вигляд волосся та поєднують ефективність із комфортним щоденним доглядом.','["Суха шкіра голови","Схильна до лущення шкіра голови","Чутлива шкіра голови"]','["Зменшення дискомфорту шкіри голови","Очищення від лущення"]','["Допомагає усунути лупу","Заспокоює свербіж","Підтримує баланс"]','["шкіра голови","лущення","комфорт"]','/images/daily-naturals/daily-naturals-scalp-clearing.webp'),('daily-naturals-care-collection','daily-naturals','Care Collection','Додатковий зволожувальний, захисний і незмивний догляд','Лінійка Daily Naturals для потреби «додатковий догляд». Професійні формули Clean Beauty підтримують здоровий вигляд волосся та поєднують ефективність із комфортним щоденним доглядом.','["Сухе","Пошкоджене","Сплутане","Усі типи волосся"]','["Додатковий догляд","Захист і полегшення розчісування"]','["Зволожує","Полегшує розчісування","Захищає довжину"]','["догляд","захист","м’якість"]','/images/daily-naturals/daily-naturals-care-collection.webp'),('daily-naturals-styling','daily-naturals','Styling','Формування текстури, локонів і контроль укладки','Лінійка Daily Naturals для потреби «створення укладки». Професійні формули Clean Beauty підтримують здоровий вигляд волосся та поєднують ефективність із комфортним щоденним доглядом.','["Кучеряве","Хвилясте","Усі типи волосся"]','["Створення укладки","Формування локонів і текстури"]','["Допомагає контролювати форму","Підкреслює текстуру","Зберігає природний рух"]','["стайлінг","текстура","локони"]','/images/daily-naturals/daily-naturals-styling.webp'),('esla-lucent-color','esla','Lucent Color','Збереження кольору та зволоження фарбованого волосся','Професійна лінійка ESLA Italy для потреби «збереження насиченості кольору». Формули поєднують цілеспрямований догляд, сучасні активні компоненти та комфортне застосування.','["Фарбоване","Натуральне","Сухе"]','["Збереження насиченості кольору","Зволоження"]','["Підтримує колір","Надає блиску","Допомагає зберігати м’якість"]','["колір","зелена кава","зволоження"]','/images/esla/esla-lucent-color.webp'),('esla-hydra-special','esla','Hydra Special','Тривале зволоження сухого та ламкого волосся','Професійна лінійка ESLA Italy для потреби «тривале зволоження». Формули поєднують цілеспрямований догляд, сучасні активні компоненти та комфортне застосування.','["Нормальне","Сухе","Ламке","Жорстке"]','["Тривале зволоження","Пом’якшення"]','["Підтримує вологу","Надає м’якості","Підсилює блиск"]','["волога","м’якість","манна"]','/images/esla/esla-hydra-special.webp') ON CONFLICT(id) DO UPDATE SET brand_id=excluded.brand_id,name=excluded.name,short_description=excluded.short_description,description=excluded.description,hair_types=excluded.hair_types,purposes=excluded.purposes,benefits=excluded.benefits,keywords=excluded.keywords,image=excluded.image;
INSERT INTO product_lines (id,brand_id,name,short_description,description,hair_types,purposes,benefits,keywords,image) VALUES ('esla-repair-prestige','esla','Repair Prestige','Відновлення та захист пошкодженого волосся','Професійна лінійка ESLA Italy для потреби «відновлення пошкодженого волосся». Формули поєднують цілеспрямований догляд, сучасні активні компоненти та комфортне застосування.','["Пошкоджене","Дуже пошкоджене","Ламке"]','["Відновлення пошкодженого волосся","Захист від зовнішніх факторів"]','["Сприяє відновленню","Зміцнює полотно волосся","Захищає від пошкоджень"]','["відновлення","протеїни","захист"]','/images/esla/esla-repair-prestige.webp'),('esla-frizz-dominator','esla','Frizz Dominator','Розгладження та контроль пухнастого волосся','Професійна лінійка ESLA Italy для потреби «контроль пухнастості». Формули поєднують цілеспрямований догляд, сучасні активні компоненти та комфортне застосування.','["Пухнасте","Жорстке","Неслухняне"]','["Контроль пухнастості","Захист від вологості"]','["Розгладжує","Полегшує укладання","Захищає від вологості"]','["гладкість","фітокератин","вологість"]','/images/esla/esla-frizz-dominator.webp'),('esla-volume-supreme','esla','Volume Supreme','Об’єм і густота для тонкого волосся','Професійна лінійка ESLA Italy для потреби «надання об’єму». Формули поєднують цілеспрямований догляд, сучасні активні компоненти та комфортне застосування.','["Тонке","Позбавлене об’єму"]','["Надання об’єму","Збільшення відчуття густоти"]','["Додає об’єму","Надає щільності","Не обтяжує"]','["об’єм","густота","липа"]','/images/esla/esla-volume-supreme.webp'),('esla-curl-couture','esla','Curl Couture','Пружні, окреслені локони без пухнастості','Професійна лінійка ESLA Italy для потреби «формування локонів». Формули поєднують цілеспрямований догляд, сучасні активні компоненти та комфортне застосування.','["Кучеряве","Хвилясте","Пухнасте"]','["Формування локонів","Контроль пухнастості"]','["Підкреслює форму локонів","Надає м’якості","Зменшує пухнастість"]','["локони","пружність","баобаб"]','/images/esla/esla-curl-couture.webp'),('esla-daily','esla','Daily','Щоденний догляд, адаптований до товщини волосся','Професійна лінійка ESLA Italy для потреби «щоденне очищення та догляд». Формули поєднують цілеспрямований догляд, сучасні активні компоненти та комфортне застосування.','["Тонке","Середньої товщини","Густе","Усі типи волосся"]','["Щоденне очищення та догляд","Підготовка до укладання"]','["Підтримує м’якість","Надає природного блиску","Допомагає контролювати пухнастість"]','["щодня","товщина волосся","блиск"]','/images/esla/esla-daily.webp'),('esla-calming','esla','Calming','Заспокійливий догляд для чутливої шкіри голови','Професійна лінійка ESLA Italy для потреби «заспокоєння шкіри голови». Формули поєднують цілеспрямований догляд, сучасні активні компоненти та комфортне застосування.','["Чутлива шкіра голови","Подразнена шкіра голови"]','["Заспокоєння шкіри голови","Зменшення відчуття дискомфорту"]','["Заспокоює","Підтримує захисний бар’єр","Допомагає зберігати зволоження"]','["комфорт","чутливість","albatrellus"]','/images/esla/esla-calming.webp'),('esla-sebum-controller','esla','Sebum Controller','Контроль себуму та свіжість жирної шкіри голови','Професійна лінійка ESLA Italy для потреби «контроль надмірної жирності». Формули поєднують цілеспрямований догляд, сучасні активні компоненти та комфортне застосування.','["Жирна шкіра голови","Схильне до жирності"]','["Контроль надмірної жирності","Тривале відчуття чистоти"]','["Абсорбує надлишок себуму","Не обтяжує","Подовжує свіжість"]','["себум","свіжість","баланс"]','/images/esla/esla-sebum-controller.webp'),('esla-detox','esla','Detox','Очищення шкіри голови, схильної до лущення','Професійна лінійка ESLA Italy для потреби «профілактика видимого лущення». Формули поєднують цілеспрямований догляд, сучасні активні компоненти та комфортне застосування.','["Схильна до лущення шкіра голови","Суха лупа","Жирна лупа"]','["Профілактика видимого лущення","Глибоке очищення"]','["Очищає шкіру голови","Допомагає зменшити лущення","Надає відчуття свіжості"]','["детокс","лущення","свіжість"]','/images/esla/esla-detox.webp'),('esla-energy','esla','Energy','Зміцнювальний догляд для ослабленого волосся','Професійна лінійка ESLA Italy для потреби «зміцнення ослабленого волосся». Формули поєднують цілеспрямований догляд, сучасні активні компоненти та комфортне застосування.','["Слабке","Ламке","Схильне до стоншення","Чутлива шкіра голови"]','["Зміцнення ослабленого волосся","Підтримка густоти"]','["Надає життєвої сили","Допомагає протидіяти стоншенню","Підтримує шкіру голови"]','["енергія","густота","грейпфрут"]','/images/esla/esla-energy.webp'),('esla-blonde-care','esla','Blonde Care','Нейтралізація жовтих і помаранчевих відтінків блонду','Професійна лінійка ESLA Italy для потреби «нейтралізація небажаних відтінків». Формули поєднують цілеспрямований догляд, сучасні активні компоненти та комфортне застосування.','["Освітлене","Блонд","Сиве","Меліроване"]','["Нейтралізація небажаних відтінків","Догляд за освітленим волоссям"]','["Коригує теплі відтінки","Надає м’якості","Підсилює блиск"]','["блонд","пігмент","нейтралізація"]','/images/esla/esla-blonde-care.webp') ON CONFLICT(id) DO UPDATE SET brand_id=excluded.brand_id,name=excluded.name,short_description=excluded.short_description,description=excluded.description,hair_types=excluded.hair_types,purposes=excluded.purposes,benefits=excluded.benefits,keywords=excluded.keywords,image=excluded.image;
INSERT INTO products (id,brand_id,line_id,name,category,description,purpose,image,usage) VALUES ('daily-naturals-everyday-balancing-shampoo','daily-naturals','daily-naturals-everyday-balancing','Everyday Balancing Shampoo','Шампунь','Делікатно очищає та м’яко очищає. Формула підтримує доглянутий вигляд волосся й доповнює систему Everyday Balancing.','Очищення: щоденний збалансований догляд','/images/daily-naturals/daily-naturals-everyday-balancing-shampoo.webp','Нанесіть шампунь на волосся та ретельно спіньте. залиште на 2 хвилини, після чого змийте та повторіть процедуру. для максимального ефекту використовуйте разом із everyday balancing conditioner.'),('daily-naturals-everyday-balancing-conditioner','daily-naturals','daily-naturals-everyday-balancing','Everyday Balancing Conditioner','Кондиціонер','Полегшує розчісування та м’яко очищає. Формула підтримує доглянутий вигляд волосся й доповнює систему Everyday Balancing.','Кондиціонування: щоденний збалансований догляд','/images/daily-naturals/daily-naturals-everyday-balancing-conditioner.webp','Після миття голови нанесіть кондиціонер на волосся, рівномірно розподіліть від коренів до кінчиків. залиште на 2 хвилини, після чого ретельно змийте.'),('daily-naturals-intense-hydrating-shampoo','daily-naturals','daily-naturals-intense-hydrating','Intense Hydrating Shampoo','Шампунь','Делікатно очищає та насичує вологою. Формула підтримує доглянутий вигляд волосся й доповнює систему Intense Hydrating.','Очищення: глибоке зволоження','/images/daily-naturals/daily-naturals-intense-hydrating-shampoo.webp','Нанесіть шампунь на волосся та ретельно спіньте. залиште на 2 хвилини, після чого змийте та повторіть процедуру. для найкращого результату використовуйте разом з кондиціонером intense hydrating conditioner.'),('daily-naturals-intense-hydrating-conditioner','daily-naturals','daily-naturals-intense-hydrating','Intense Hydrating Conditioner','Кондиціонер','Полегшує розчісування та насичує вологою. Формула підтримує доглянутий вигляд волосся й доповнює систему Intense Hydrating.','Кондиціонування: глибоке зволоження','/images/daily-naturals/daily-naturals-intense-hydrating-conditioner.webp','Після миття голови нанесіть кондиціонер на волосся, рівномірно розподіліть від коренів до кінчиків. залиште на 2 хвилини, після чого ретельно змийте.'),('daily-naturals-full-bodied-volumising-shampoo','daily-naturals','daily-naturals-full-bodied-volumising','Full-Bodied Volumising Shampoo','Шампунь','Делікатно очищає та додає пишності. Формула підтримує доглянутий вигляд волосся й доповнює систему Full-Bodied Volumising.','Очищення: надання об’єму','/images/daily-naturals/daily-naturals-full-bodied-volumising-shampoo.webp','Нанесіть шампунь на волосся та ретельно спіньте. залиште на 2 хвилини, після чого змийте та повторіть процедуру. для найкращого результату використовуйте разом із кондиціонером full-bodied volumising conditioner.'),('daily-naturals-full-bodied-volumising-conditioner','daily-naturals','daily-naturals-full-bodied-volumising','Full-Bodied Volumising Conditioner','Кондиціонер','Полегшує розчісування та додає пишності. Формула підтримує доглянутий вигляд волосся й доповнює систему Full-Bodied Volumising.','Кондиціонування: надання об’єму','/images/daily-naturals/daily-naturals-full-bodied-volumising-conditioner.webp','Після миття голови нанесіть кондиціонер на волосся, рівномірно розподіліть від коренів до кінчиків. залиште на 2 хвилини, після чого ретельно змийте.'),('daily-naturals-anti-frizz-smoothing-shampoo','daily-naturals','daily-naturals-anti-frizz-smoothing','Anti-Frizz Smoothing Shampoo','Шампунь','Делікатно очищає та пом’якшує. Формула підтримує доглянутий вигляд волосся й доповнює систему Anti-Frizz Smoothing.','Очищення: контроль пухнастості','/images/daily-naturals/daily-naturals-anti-frizz-smoothing-shampoo.webp','Нанесіть шампунь на волосся і ретельно спіньте. залиште на 2 хвилини, після чого змийте та повторіть процедуру. для найкращого результату використовуйте разом із кондиціонером anti-frizz smoothing conditioner.'),('daily-naturals-anti-frizz-smoothing-conditioner','daily-naturals','daily-naturals-anti-frizz-smoothing','Anti-Frizz Smoothing Conditioner','Кондиціонер','Полегшує розчісування та пом’якшує. Формула підтримує доглянутий вигляд волосся й доповнює систему Anti-Frizz Smoothing.','Кондиціонування: контроль пухнастості','/images/daily-naturals/daily-naturals-anti-frizz-smoothing-conditioner.webp','Після миття голови нанесіть кондиціонер на волосся, рівномірно розподіліть від коренів до кінчиків. залиште на 2 хвилини, після чого ретельно змийте.'),('daily-naturals-blonde-toning-shampoo','daily-naturals','daily-naturals-blonde-toning','Blonde Toning Shampoo','Шампунь','Делікатно очищає та освіжає блонд. Формула підтримує доглянутий вигляд волосся й доповнює систему Blonde Toning.','Очищення: нейтралізація жовтизни','/images/daily-naturals/daily-naturals-blonde-toning-shampoo.webp','Нанесіть шампунь на волосся і ретельно спіньте. залиште на 2–5 хвилин для підтримки відтінку блонд або довше за потреби. після цього змийте та повторіть процедуру. для найкращого результату використовуйте разом із blonde toning conditioner.'),('daily-naturals-blonde-toning-conditioner','daily-naturals','daily-naturals-blonde-toning','Blonde Toning Conditioner','Кондиціонер','Полегшує розчісування та освіжає блонд. Формула підтримує доглянутий вигляд волосся й доповнює систему Blonde Toning.','Кондиціонування: нейтралізація жовтизни','/images/daily-naturals/daily-naturals-blonde-toning-conditioner.webp','Після миття голови нанесіть кондиціонер на волосся, рівномірно розподіліть від коренів до кінчиків. залиште на 2–5 хвилин для підтримки відтінку блонд або довше за потреби, після чого ретельно змийте.'),('daily-naturals-scalp-clearing-shampoo','daily-naturals','daily-naturals-scalp-clearing','Scalp Clearing Shampoo','Шампунь','Делікатно очищає та допомагає усунути лупу. Формула підтримує доглянутий вигляд волосся й доповнює систему Scalp Clearing.','Очищення: зменшення дискомфорту шкіри голови','/images/daily-naturals/daily-naturals-scalp-clearing-shampoo.webp','Нанесіть шампунь на волосся і ретельно спіньте. залиште на 2–5 хвилин, після чого ретельно змийте та за потреби повторіть. для найкращого результату використовуйте разом із вашим улюбленим кондиціонером daily naturals.') ON CONFLICT(id) DO UPDATE SET brand_id=excluded.brand_id,line_id=excluded.line_id,name=excluded.name,category=excluded.category,description=excluded.description,purpose=excluded.purpose,image=excluded.image,usage=excluded.usage;
INSERT INTO products (id,brand_id,line_id,name,category,description,purpose,image,usage) VALUES ('daily-naturals-moisture-mask','daily-naturals','daily-naturals-care-collection','Moisture Mask','Маска','Забезпечує інтенсивний догляд та зволожує. Формула підтримує доглянутий вигляд волосся й доповнює систему Care Collection.','Інтенсивний догляд: додатковий догляд','/images/daily-naturals/daily-naturals-moisture-mask.webp','Після миття голови нанесіть зволожуючу маску, рівномірно розподіляючи по волоссю масажуючими рухами. залиште на 5 хвилин або довше за потреби, після чого ретельно змийте. за потреби використовуйте разом із вашим улюбленим кондиціонером dn.'),('daily-naturals-detangler-thermal-protection','daily-naturals','daily-naturals-care-collection','Detangler with Thermal Protection','Спрей','Забезпечує незмивний догляд та зволожує. Формула підтримує доглянутий вигляд волосся й доповнює систему Care Collection.','Незмивний догляд: додатковий догляд','/images/daily-naturals/daily-naturals-detangler-thermal-protection.webp','Розпиліть на сухе або вологе волосся перед сушінням. розчешіть волосся для рівномірного розподілення засобу та полегшення розплутування. після висихання можна використовувати гарячі інструменти для укладання. за потреби комбінуйте з іншими засобами догляду та стайлінгу.'),('daily-naturals-defender-leave-in-conditioner','daily-naturals','daily-naturals-care-collection','Defender Leave In Conditioner','Кондиціонер','Полегшує розчісування та зволожує. Формула підтримує доглянутий вигляд волосся й доповнює систему Care Collection.','Кондиціонування: додатковий догляд','/images/daily-naturals/daily-naturals-defender-leave-in-conditioner.webp','Нанесіть невелику кількість засобу на долоні та рівномірно розподіліть по вологому або сухому волоссю від середини довжини до кінчиків. рекомендується використовувати перед плаванням або перебуванням на відкритому повітрі.'),('daily-naturals-ends-sealer-leave-in-treatment','daily-naturals','daily-naturals-care-collection','Ends Sealer Leave In Treatment','Крем','Допомагає сформувати укладку та зволожує. Формула підтримує доглянутий вигляд волосся й доповнює систему Care Collection.','Формування та контроль укладки: додатковий догляд','/images/daily-naturals/daily-naturals-ends-sealer-leave-in-treatment.webp','Нанесіть невелику кількість засобу на долоні та рівномірно розподіліть по вологому або сухому волоссю від середини довжини до кінчиків. для додаткового розгладження та контролю пухнастості наносьте за потреби на окремі ділянки волосся.'),('daily-naturals-form-hybrid-styling-lotion','daily-naturals','daily-naturals-styling','Form Hybrid Styling Lotion','Лосьйон','Забезпечує концентрований догляд та допомагає контролювати форму. Формула підтримує доглянутий вигляд волосся й доповнює систему Styling.','Концентрований догляд: створення укладки','/images/daily-naturals/daily-naturals-form-hybrid-styling-lotion.webp','Нанесіть невелику кількість засобу на долоні та рівномірно розподіліть по вологому волоссю. висушіть феном або залиште висихати природним шляхом. після висихання волосся можна використовувати гарячі інструменти для укладання для створення легкої та гнучкої фіксації.'),('daily-naturals-curl-cream','daily-naturals','daily-naturals-styling','Curl Cream','Крем','Допомагає сформувати укладку та допомагає контролювати форму. Формула підтримує доглянутий вигляд волосся й доповнює систему Styling.','Формування та контроль укладки: створення укладки','/images/daily-naturals/daily-naturals-curl-cream.webp','Рівномірно нанесіть засіб на підсушене рушником волосся стискаючими рухами або розподіляючи по довжині. залиште волосся висихати природним шляхом або використовуйте дифузор для більшого об’єму та чіткішої фіксації завитка.'),('esla-lucent-color-shampoo','esla','esla-lucent-color','Lucent Color Шампунь','Шампунь','Зволожуючий шампунь для збереження кольору волосся. Формула, збагачена ферментованою зеленою кавою та глюконатом натрію, сприяє тривалому збереженню насиченості кольору, природного блиску та доглянутого вигляду волосся.','Очищення: збереження насиченості кольору','/images/esla/esla-lucent-color-shampoo.webp','Нанести шампунь на вологе волосся, м’якими масажними рухами помасажувати шкіру голови, ретельно змити водою.'),('esla-lucent-color-conditioner','esla','esla-lucent-color','Lucent Color Кондиціонер','Кондиціонер','Зволожувальний кондиціонер для збереження кольору волосся. Делікатно розплутує волосся, кондиціонує його, робить м’яким і слухняним. Формула, збагачена ферментованою зеленою кавою та глюконатом натрію, сприяє тривалому збереженню насиченості кольору, природного блиску та доглянутого вигляду волосся.','Кондиціонування: збереження насиченості кольору','/images/esla/esla-lucent-color-conditioner.webp','Після використання шампуню нанести кондиціонер на вологе волосся, рівномірно розподілити по довжині та на кінчики, залишити на кілька хвилин, після чого ретельно змити водою.'),('esla-lucent-color-mask','esla','esla-lucent-color','Lucent Color Маска','Маска','Живильна маска для збереження кольору волосся. Формула, збагачена ферментованою зеленою кавою та глюконатом натрію, сприяє тривалому збереженню насиченості кольору, природного блиску та доглянутого вигляду волосся. Ретельно підібрані інгредієнти природного походження, зокрема олія жожоба, забезпечують догляд за зневодненим, схильним до пухнастості волоссям.','Інтенсивний догляд: збереження насиченості кольору','/images/esla/esla-lucent-color-mask.webp','Після використання шампуню нанести маску на вологе волосся, рівномірно розподілити по довжині та на кінчики. Залишити на 5–10 хвилин, після чого ретельно змити водою. Використовувати 1–2 рази на тиждень або регулярно для особливо пошкодженого волосся.'),('esla-hydra-special-shampoo','esla','esla-hydra-special','Hydra Special Шампунь','Шампунь','Зволожувальний шампунь, що дбайливо очищає волосся та підсилює його природний блиск. Формула, збагачена сицилійським фітокомплексом Манна з гір Мадоні з унікальними зволожувальними властивостями, надає волоссю м’якості та забезпечує тривале зволоження.','Очищення: тривале зволоження','/images/esla/esla-hydra-special-shampoo.webp','Нанести шампунь на вологе волосся, м’якими масажними рухами помасажувати шкіру голови, після чого ретельно змити водою.'),('esla-hydra-special-conditioner','esla','esla-hydra-special','Hydra Special Кондиціонер','Кондиціонер','Живильний кондиціонер для нормального, сухого та ламкого волосся. Формула, збагачена сицилійським фітокомплексом Манна з гір Мадоні з унікальними зволожувальними властивостями, надає волоссю м’якості, забезпечує тривале зволоження, кондиціонує волосся, не обтяжуючи його, та полегшує розчісування.','Кондиціонування: тривале зволоження','/images/esla/esla-hydra-special-conditioner.webp','Після використання шампуню нанести кондиціонер на вологе волосся, рівномірно розподілити по довжині та на кінчики, залишити на кілька хвилин, після чого ретельно змити водою.') ON CONFLICT(id) DO UPDATE SET brand_id=excluded.brand_id,line_id=excluded.line_id,name=excluded.name,category=excluded.category,description=excluded.description,purpose=excluded.purpose,image=excluded.image,usage=excluded.usage;
INSERT INTO products (id,brand_id,line_id,name,category,description,purpose,image,usage) VALUES ('esla-hydra-special-mask','esla','esla-hydra-special','Hydra Special Маска','Маска','Маска для тривалого зволоження нормального, сухого та ламкого волосся. Формула з сицилійським фітокомплексом Манна з гір Мадоні та олією ши інтенсивно живить волосся, робить його м’яким, доглянутим і слухняним.','Інтенсивний догляд: тривале зволоження','/images/esla/esla-hydra-special-mask.webp','Після використання шампуню нанести маску на вологе волосся, рівномірно розподілити по довжині та на кінчики. Залишити на 5–10 хвилин, після чого ретельно змити водою. Використовувати 1–2 рази на тиждень або частіше за потреби.'),('esla-hydra-special-serum','esla','esla-hydra-special','Hydra Special Сироватка','Сироватка','Інтенсивно зволожувальна сироватка для нормального, сухого та ламкого волосся. Забезпечує миттєвий догляд, блиск і м’якість.','Концентрований догляд: тривале зволоження','/images/esla/esla-hydra-special-serum.webp','Нанести на чисте вологе волосся по довжині та на кінчики, залишити на кілька хвилин, після чого ретельно змити.'),('esla-repair-prestige-shampoo','esla','esla-repair-prestige','Repair Prestige Шампунь','Шампунь','Захисний та відновлювальний шампунь. М’яка формула очищає волосся, сприяючи його відновленню та захищаючи від зовнішніх факторів. Містить Repair-Care Tech — поєднання біотехнологічних компонентів, отриманих із грибів, та веганських протеїнів із відновлювальними й захисними властивостями.','Очищення: відновлення пошкодженого волосся','/images/esla/esla-repair-prestige-shampoo.webp','Нанести на вологе волосся, спінити масажними рухами, ретельно змити водою.'),('esla-repair-prestige-spray','esla','esla-repair-prestige','Repair Prestige Відновлювальний спрей','Спрей','Захисний та відновлювальний догляд. Інноваційна формула кондиціонує й живить волосся, сприяючи його інтенсивному відновленню та захищаючи від впливу зовнішніх факторів. Містить комплекс Repair-Care Tech — поєднання біотехнологічних компонентів грибного походження та веганських протеїнів із відновлювальними й захисними властивостями.','Незмивний догляд: відновлення пошкодженого волосся','/images/esla/esla-repair-prestige-spray.webp','Після миття шампунем розпилити засіб на волосся, приділяючи особливу увагу пошкодженим ділянкам. Залишити на 5 хвилин. Не змивати. Залежно від типу волосся використати кондиціонер або маску РІПЕА ПРЕСТІЖ.'),('esla-repair-prestige-conditioner','esla','esla-repair-prestige','Repair Prestige Кондиціонер','Кондиціонер','Захисний та відновлювальний кондиціонер. Кондиціонує волосся, не обтяжуючи його. Сприяє відновленню волосся та захищає його від впливу зовнішніх факторів. Містить комплекс Repair-Care Tech — поєднання біотехнологічних компонентів грибного походження та веганських протеїнів із відновлювальними й захисними властивостями.','Кондиціонування: відновлення пошкодженого волосся','/images/esla/esla-repair-prestige-conditioner.webp','Нанести на чисте вологе волосся після використання шампуню, залишити на 2–3 хвилини, потім ретельно змити.'),('esla-repair-prestige-mask','esla','esla-repair-prestige','Repair Prestige Маска','Маска','Захисна та відновлювальна маска. Кондиціонує й живить волосся, сприяючи його інтенсивному відновленню та захищаючи від впливу зовнішніх факторів. Містить комплекс Repair-Care Tech — поєднання біотехнологічних компонентів грибного походження та веганських протеїнів із відновлювальними й захисними властивостями.','Інтенсивний догляд: відновлення пошкодженого волосся','/images/esla/esla-repair-prestige-mask.webp','Нанести на чисте вологе волосся після використання шампуню, залишити на 10 хвилин, потім ретельно змити.'),('esla-repair-prestige-thermal-spray','esla','esla-repair-prestige','Repair Prestige Термозахисний спрей','Спрей','Захисний та відновлювальний термозахисний засіб. Сприяє відновленню волосся та захищає його від впливу високих температур під час укладання. Містить комплекс Repair-Care Tech — поєднання біотехнологічних компонентів грибного походження та веганських протеїнів із відновлювальними й захисними властивостями.','Незмивний догляд: відновлення пошкодженого волосся','/images/esla/esla-repair-prestige-thermal-spray.webp','Рівномірно нанести на чисте вологе волосся перед укладанням із використанням термоінструментів.'),('esla-repair-prestige-oil-serum','esla','esla-repair-prestige','Repair Prestige Олія-сироватка','Олія-сироватка','Захисна та відновлювальна олія-сироватка. Інноваційна формула надає волоссю блиску й живить його, сприяючи відновленню та захищаючи від впливу зовнішніх факторів. Містить комплекс Phyto Repair-Care Tech — поєднання компонентів рослинного походження з відновлювальними й захисними властивостями.','Фінішний догляд: відновлення пошкодженого волосся','/images/esla/esla-repair-prestige-oil-serum.webp','Нанести на сухе волосся як завершальний етап після укладання.'),('esla-frizz-dominator-shampoo','esla','esla-frizz-dominator','Frizz Dominator Шампунь','Шампунь','Шампунь для волосся, схильного до пухнастості. Сприяє зволоженню та надає природного блиску. Збагачений рослинним фітокератином, отриманим шляхом біоензимної обробки конопель і рису. Його плівкоутворювальні властивості допомагають покривати поверхню волосся, сприяючи зволоженню, м’якості та захисту від впливу вологи.','Очищення: контроль пухнастості','/images/esla/esla-frizz-dominator-shampoo.webp','Нанести на вологе волосся, м’якими масажними рухами спінити, потім ретельно змити.'),('esla-frizz-dominator-mask','esla','esla-frizz-dominator','Frizz Dominator Маска','Маска','Маска з вираженими кондиціонувальними властивостями для волосся, схильного до пухнастості. Допомагає полегшити розчісування та захистити волосся від впливу вологи. Рослинний фітокератин, отриманий шляхом біоензимної обробки конопель і рису, у поєднанні з натуральними компонентами та олією жожоба сприяє м’якості волосся й допомагає захистити його від впливу вологи.','Інтенсивний догляд: контроль пухнастості','/images/esla/esla-frizz-dominator-mask.webp','Після миття шампунем нанести на вологе волосся, рівномірно розподілити по всій довжині та на кінчики. Залишити на 5–10 хвилин, потім ретельно змити. Використовувати регулярно, якщо волосся густе, важко розчісується та особливо схильне до пухнастості.'),('esla-frizz-dominator-spray','esla','esla-frizz-dominator','Frizz Dominator Спрей','Спрей','Незмивний догляд для неслухняного волосся, схильного до пухнастості. Сприяє зволоженню та допомагає захистити волосся від впливу вологи, роблячи його м’яким, блискучим і легшим у розчісуванні. Комплекс фітокератинів і натуральних рослинних полімерів забезпечує кондиціонувальний ефект, сприяє розгладженню волосся та полегшує його укладання.','Незмивний догляд: контроль пухнастості','/images/esla/esla-frizz-dominator-spray.webp','Рівномірно розпилити засіб по всій довжині волосся, після чого приступати до сушіння.') ON CONFLICT(id) DO UPDATE SET brand_id=excluded.brand_id,line_id=excluded.line_id,name=excluded.name,category=excluded.category,description=excluded.description,purpose=excluded.purpose,image=excluded.image,usage=excluded.usage;
INSERT INTO products (id,brand_id,line_id,name,category,description,purpose,image,usage) VALUES ('esla-frizz-dominator-serum','esla','esla-frizz-dominator','Frizz Dominator Сироватка','Сироватка','Незмивний зволожувальний догляд. Допомагає зменшити пухнастість волосся завдяки плівкоутворювальним властивостям.','Концентрований догляд: контроль пухнастості','/images/esla/esla-frizz-dominator-serum.webp','Після використання маски ФРІЗ ДОМІНАТОР промокнути волосся рушником, щоб прибрати надлишок вологи, нанести сироватку та переходити до сушіння й укладання волосся.'),('esla-volume-supreme-shampoo','esla','esla-volume-supreme','Volume Supreme Шампунь','Шампунь','Шампунь для надання об’єму тонкому волоссю та волоссю, позбавленому пишності. Бруньки липи, що залишаються після виробництва чаю, є цінним джерелом полісахаридів, флавоноїдів і глікопротеїнів. Вони покривають поверхню волосся, надаючи йому більшого об’єму та густоти.','Очищення: надання об’єму','/images/esla/esla-volume-supreme-shampoo.webp','Нанести на вологе волосся, м’якими масажними рухами помасажувати шкіру голови, потім ретельно змити.'),('esla-volume-supreme-elixir','esla','esla-volume-supreme','Volume Supreme Еліксир','Еліксир','Незмивний засіб для надання об’єму. Екстракт бруньок липи, отриманий із сировини, що залишається після виробництва чаю, у поєднанні з інноваційним катіонним кополімером на основі протеїнів пшениці сприяє наданню волоссю більшої густоти та об''єму.','Незмивний догляд: надання об’єму','/images/esla/esla-volume-supreme-elixir.webp','Рівномірно розпилити засіб по всій довжині волосся, після чого приступати до сушіння.'),('esla-curl-couture-shampoo','esla','esla-curl-couture','Curl Couture Shampoo','Шампунь','М’яко очищає, підкреслює природну форму хвиль і локонів та допомагає зменшити пухнастість.','Очищення: формування локонів','/images/esla/esla-curl-couture-shampoo.webp','Нанести на вологе волосся, спінити масажними рухами та ретельно змити. За потреби повторити.'),('esla-curl-couture-conditioner','esla','esla-curl-couture','Curl Couture Conditioner','Кондиціонер','Кондиціонує кучеряве волосся, надає м’якості, полегшує розчісування та підтримує форму локонів.','Кондиціонування: формування локонів','/images/esla/esla-curl-couture-conditioner.webp','Нанести на чисте вологе волосся, залишити на кілька хвилин і ретельно змити.'),('esla-curl-couture-mask','esla','esla-curl-couture','Curl Couture Mask','Маска','Інтенсивно пом’якшує кучеряве волосся, робить локони слухнянішими та допомагає контролювати пухнастість.','Інтенсивний догляд: формування локонів','/images/esla/esla-curl-couture-mask.webp','Нанести після шампуню на вологе волосся, залишити на 10–15 хвилин і змити. Використовувати 1–2 рази на тиждень.'),('esla-curl-couture-perfecting-cream','esla','esla-curl-couture','Curl Couture Perfecting Cream','Крем','Незмивний крем надає локонам чіткішої форми, м’якості та допомагає контролювати пухнастість.','Формування та контроль укладки: формування локонів','/images/esla/esla-curl-couture-perfecting-cream.webp','Нанести на чисте вологе волосся та виконати укладання. На сухому волоссі можна використовувати як фінішний засіб.'),('esla-daily-fine-hair-shampoo','esla','esla-daily','Daily Fine Hair Шампунь','Шампунь','Живильний шампунь для тонкого волосся. Делікатно очищає волосся, не обтяжуючи його. Завдяки формулі, збагаченій екстрактом лимона, забезпечує кондиціонувальний догляд і надає волоссю природного блиску.','Очищення: щоденне очищення та догляд','/images/esla/esla-daily-fine-hair-shampoo.webp','Рівномірно нанести на вологе волосся, спінити легкими масажними рухами, потім ретельно змити.'),('esla-daily-fine-hair-conditioner','esla','esla-daily','Daily Fine Hair Кондиціонер','Кондиціонер','Живильний кондиціонер для тонкого волосся. Має пом’якшувальну дію, надає волоссю природного блиску. Формула збагачена олією жожоба та екстрактом бурих водоростей.','Кондиціонування: щоденне очищення та догляд','/images/esla/esla-daily-fine-hair-conditioner.webp','Після миття шампунем нанести на вологе волосся по всій довжині та на кінчики, залишити на 2–3 хвилини, потім ретельно змити.'),('esla-style-elite-shine-lotion','esla','esla-daily','Style Elite Лосьйон для блиску','Лосьйон','Рідкий кондиціонер для тонкого волосся, що кондиціонує та надає блиску. Формула, збагачена екстрактом лимона, сприяє зволоженню волосся, надає йому природного блиску вже за кілька секунд, полегшує розчісування та робить волосся візуально більш гладеньким і доглянутим.','Концентрований догляд: щоденне очищення та догляд','/images/esla/esla-style-elite-shine-lotion.webp','Після миття шампунем нанести засіб по всій довжині волосся та на кінчики, помасажувати протягом 10 секунд, потім ретельно змити. Для посилення блиску використовувати не частіше двох разів на тиждень.'),('esla-style-elite-multifunctional-mousse','esla','esla-daily','Style Elite Багатофункціональний мус','Мус','Мус для розгладження та живлення тонкого волосся й волосся середньої товщини. Надає волоссю об’єму, природного блиску та м’якості завдяки формулі, збагаченій екстрактом лимона.','Легке кондиціонування: щоденне очищення та догляд','/images/esla/esla-style-elite-multifunctional-mousse.webp','Рівномірно розподілити засіб по всій довжині та на кінчики вологого волосся, після чого виконати бажане укладання. Для більш вираженого ефекту укладання нанести невелику кількість засобу на сухе волосся як завершальний етап. Не змивати.') ON CONFLICT(id) DO UPDATE SET brand_id=excluded.brand_id,line_id=excluded.line_id,name=excluded.name,category=excluded.category,description=excluded.description,purpose=excluded.purpose,image=excluded.image,usage=excluded.usage;
INSERT INTO products (id,brand_id,line_id,name,category,description,purpose,image,usage) VALUES ('esla-style-elite-multifunctional-serum','esla','esla-daily','Style Elite Багатофункціональна сироватка','Сироватка','Живильна сироватка для надання блиску всім типам волосся. Формула, збагачена олією вечірньої примули, допомагає контролювати пухнастість волосся та надає йому миттєвого природного блиску.','Концентрований догляд: щоденне очищення та догляд','/images/esla/esla-style-elite-multifunctional-serum.webp','Перед сушінням феном нанести засіб по всій довжині волосся та на кінчики. Для особливо пухнастого або сухого волосся використовувати як завершальний етап після укладання. Не змивати.'),('esla-daily-thick-hair-shampoo','esla','esla-daily','Daily Thick Hair Шампунь','Шампунь','Живильний шампунь для волосся середньої товщини та густого волосся. Формула, збагачена екстрактом бурих водоростей, делікатно очищає волосся, залишаючи його зволоженим і блискучим.','Очищення: щоденне очищення та догляд','/images/esla/esla-daily-thick-hair-shampoo.webp','Рівномірно нанести на вологе волосся, спінити легкими масажними рухами, потім ретельно змити.'),('esla-daily-thick-hair-mask','esla','esla-daily','Daily Thick Hair Маска','Маска','Живильна маска для волосся середньої товщини та густого волосся. Інтенсивно зволожує волосся, забезпечує пом’якшувальний догляд, робить його м’яким, блискучим і слухняним. Формула збагачена олією жожоба та екстрактом бурих водоростей.','Інтенсивний догляд: щоденне очищення та догляд','/images/esla/esla-daily-thick-hair-mask.webp','Після миття шампунем нанести на волосся по всій довжині та на кінчики, залишити на 3–10 хвилин, потім ретельно змити.'),('esla-daily-multifunctional-spray-fluid','esla','esla-daily','Daily Багатофункціональний спрей-флюїд','Спрей','Багатофункціональний спрей-флюїд для волосся середньої товщини та густого волосся. Забезпечує пом’якшувальний догляд, допомагає контролювати пухнастість волосся. Формула, збагачена екстрактами бурих водоростей і гороху, живить волосся та надає йому природного блиску.','Незмивний догляд: щоденне очищення та догляд','/images/esla/esla-daily-multifunctional-spray-fluid.webp','Перед сушінням феном рівномірно розпилити засіб по всій довжині вологого волосся та на кінчики. Для надання додаткового блиску нанести на сухе волосся як завершальний етап догляду. Не змивати.'),('esla-calming-pre-shampoo-fluid','esla','esla-calming','Calming Флюїд-прешампунь','Флюїд','Флюїд-прешампунь для подразненої шкіри голови. Допомагає захистити шкіру голови, забезпечує миттєве відчуття заспокоєння та сприяє підтриманню оптимального рівня її зволоження. Біоміметичні фітостероли, отримані з Brassica, сприяють підтриманню захисного бар’єра шкіри та допомагають зменшити відчуття дискомфорту й подразнення.','Підготовчий догляд: заспокоєння шкіри голови','/images/esla/esla-calming-pre-shampoo-fluid.webp','За потреби нанести на суху шкіру голови та м’яко помасажувати. Через 2–3 хвилини змити й використати КАЛМІНГ Шампунь заспокійливий для чутливої шкіри голови.'),('esla-calming-shampoo','esla','esla-calming','Calming Шампунь','Шампунь','Шампунь для подразненої шкіри голови. Делікатно очищає волосся та шкіру голови, допомагаючи зменшити відчуття дискомфорту. Ретельно збалансована формула забезпечує м''яке очищення та дарує миттєве відчуття заспокоєння завдяки цінним компонентам гриба Albatrellus.','Очищення: заспокоєння шкіри голови','/images/esla/esla-calming-shampoo.webp','Нанести на вологу шкіру голови та волосся, помасажувати до утворення м’якої піни, потім ретельно змити.'),('esla-calming-elixir','esla','esla-calming','Calming Заспокійливий еліксир','Еліксир','Лосьйон для відновлення балансу чутливої шкіри голови. Забезпечує миттєве відчуття заспокоєння завдяки цінним компонентам гриба Albatrellus, який природно росте в хвойних лісах Північної (бореальної) півкулі.','Незмивний догляд: заспокоєння шкіри голови','/images/esla/esla-calming-elixir.webp','Після миття шампунем нанести безпосередньо на шкіру голови та м’яко помасажувати для кращого розподілу засобу. Не змивати.'),('esla-sebum-controller-pre-shampoo','esla','esla-sebum-controller','Sebum Controller Флюїд-прешампунь','Флюїд','Флюїд пре-шампунь для жирної шкіри голови та волосся. Містить абсорбувальні порошки, які допомагають зменшити надмірне виділення себуму та підтримувати доглянутий вигляд волосся без обтяження.','Підготовчий догляд: контроль надмірної жирності','/images/esla/esla-sebum-controller-pre-shampoo.webp','Нанести на суху шкіру голови та м’яко помасажувати. Залишити на 2–3 хвилини, змити, потім вимити волосся шампунем.'),('esla-sebum-controller-shampoo','esla','esla-sebum-controller','Sebum Controller Шампунь','Шампунь','Шампунь для жирної шкіри голови та волосся. Збалансована формула забезпечує ефективне очищення, не обтяжуючи волосся. Біотехнологічний компонент морського походження сприяє нормалізації вироблення шкірного сала та допомагає довше зберігати відчуття чистоти й свіжості волосся.','Очищення: контроль надмірної жирності','/images/esla/esla-sebum-controller-shampoo.webp','Нанести на вологу шкіру голови та волосся, помасажувати до утворення м’якої піни, потім ретельно змити.'),('esla-detox-scalp-scrub','esla','esla-detox','Detox Скраб для шкіри голови','Скраб','Скраб-прешампунь для шкіри голови із сухою або жирною лупою. *Косметичний засіб для догляду за шкірою голови, що допомагає запобігати появі лущення. Забезпечує приємне відчуття свіжості та чистоти.','Глибоке очищення шкіри голови: профілактика видимого лущення','/images/esla/esla-detox-scalp-scrub.webp','Нанести на суху шкіру голови, м’яко помасажувати та залишити на 2–3 хвилини. Змити, після чого вимити волосся шампунем.'),('esla-detox-shampoo','esla','esla-detox','Detox Шампунь','Шампунь','Шампунь для шкіри голови із сухою або жирною лупою. *Косметичний засіб для догляду за шкірою голови, який сприяє її очищенню та допомагає зменшити видимі прояви лущення.','Очищення: профілактика видимого лущення','/images/esla/esla-detox-shampoo.webp','Нанести на шкіру голови та вологе волосся, помасажувати до утворення м’якої піни, потім ретельно змити.') ON CONFLICT(id) DO UPDATE SET brand_id=excluded.brand_id,line_id=excluded.line_id,name=excluded.name,category=excluded.category,description=excluded.description,purpose=excluded.purpose,image=excluded.image,usage=excluded.usage;
INSERT INTO products (id,brand_id,line_id,name,category,description,purpose,image,usage) VALUES ('esla-energy-shampoo','esla','esla-energy','Energy Тонізувальний шампунь','Шампунь','Шампунь для чутливої шкіри голови та ослабленого, схильного до стоншення волосся. Делікатно очищає, підтримує оптимальний рівень зволоження шкіри голови та забезпечує відчуття зміцнення й життєвої сили завдяки синергічній дії натурального флавоноїду, отриманого з грейпфрута, пептиду та метаболіту з листя оливи.','Очищення: зміцнення ослабленого волосся','/images/esla/esla-energy-shampoo.webp','Нанести на вологу шкіру голови та волосся, помасажувати до утворення м’якої піни, потім ретельно змити.'),('esla-energy-lotion','esla','esla-energy','Energy Тонізувальний лосьйон','Лосьйон','Тонізувальна сироватка для ослабленого та схильного до стоншення волосся. Надає волоссю об’єму та допомагає протидіяти його стоншенню завдяки синергійній дії природного флавоноїду з грейпфрута, пептиду та метаболіту з листя оливи.','Концентрований догляд: зміцнення ослабленого волосся','/images/esla/esla-energy-lotion.webp','Після миття шампунем нанести 1–2 краплі безпосередньо на шкіру голови та м’яко помасажувати для кращого розподілу засобу. Не змивати. Для інтенсивного догляду використовувати 1–2 краплі щодня протягом 10 днів, після чого перейти на підтримувальний режим — 2–3 рази на тиждень.'),('esla-blonde-care-purple-shampoo','esla','esla-blonde-care','Purple Shampoo','Шампунь','Фіолетовий шампунь із фруктовими кислотами й екстрактом чорниці нейтралізує небажані жовті відтінки та підтримує м’якість освітленого волосся.','Очищення: нейтралізація небажаних відтінків','/images/esla/esla-blonde-care-purple-shampoo.webp','Нанести на вологе волосся, рівномірно розподілити й помасажувати. Залишити до бажаного рівня нейтралізації та ретельно змити.'),('esla-blonde-care-purple-mask','esla','esla-blonde-care','Purple Hydrating Mask','Маска','Зволожувальна маска з фіолетовим пігментом нейтралізує жовті відтінки та залишає освітлене волосся м’яким і доглянутим.','Інтенсивний догляд: нейтралізація небажаних відтінків','/images/esla/esla-blonde-care-purple-mask.webp','Нанести потрібну кількість, залишити до 5 хвилин, прочесати та ретельно змити. Після Purple Shampoo ефект нейтралізації посилюється.'),('esla-blonde-care-purple-mousse','esla','esla-blonde-care','Purple Conditioning Mousse','Мус','Фіолетовий кондиціонувальний мус коригує жовті відтінки освітленого або мелірованого волосся, надає м’якості й блиску.','Легке кондиціонування: нейтралізація небажаних відтінків','/images/esla/esla-blonde-care-purple-mousse.webp','Після миття нанести на довжину та кінчики, залишити на 1–5 хвилин залежно від бажаного результату й змити.'),('esla-blonde-care-blue-mousse','esla','esla-blonde-care','Blue Conditioning Mousse','Мус','Синій кондиціонувальний мус нейтралізує небажані помаранчеві відтінки на волоссі середнього та світлого рівня тону.','Легке кондиціонування: нейтралізація небажаних відтінків','/images/esla/esla-blonde-care-blue-mousse.webp','Після миття нанести на довжину та кінчики, залишити на 1–5 хвилин залежно від бажаного результату й змити.') ON CONFLICT(id) DO UPDATE SET brand_id=excluded.brand_id,line_id=excluded.line_id,name=excluded.name,category=excluded.category,description=excluded.description,purpose=excluded.purpose,image=excluded.image,usage=excluded.usage;
